net.subscribe(render);net.onError(notify);net.onStatus(s=>{$('connection').textContent={offline:T('未连接','Offline'),replaced:T('已在其他页面打开','Open in another tab'),connecting:T('正在连接…','Connecting…'),connected:T('已连接','Connected')}[s]||s;if(current)$('ready').disabled=s!=='connected'||busy;});
$('spectate').onclick=async()=>{const code=$('room-code').value.trim();if(!code){notify(T('请输入要观战的匹配码','Enter a match code to spectate'));$('room-code').focus();return;}try{await stopMatching();location.href='online-battle.html?code='+encodeURIComponent(code)+'&spectate=1';}catch(e){notify(e.message);}};
