$('copy').onclick=async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(current.code);else{const t=document.createElement('textarea');t.value=current.code;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error();t.remove();}notify(T('匹配码已复制。','Match code copied.'));}catch{notify(T('请手动复制匹配码：','Copy the match code manually: ')+current.code);}};
$('import').onclick=()=>$('deck-file').click();$('deck-file').onchange=async e=>{const file=e.target.files[0];if(!file||lockedDeck())return;try{if(file.size>100000)throw Error(T('构筑文件过大','Deck file too large'));const data=JSON.parse(await file.text()),deck=valid(data.deck||data);decks.push(deck);selected=deck;localStorage.setItem('artifact.online.importedDeck',JSON.stringify(deck));renderDecks();notify(T('构筑已导入。不会覆盖原有单人构筑。','Deck imported — your saved single-player decks are untouched.'));}catch(e){notify(e.message);}finally{$('deck-file').value='';}};
$('share-deck').onclick=()=>{try{ArtifactDeckShare.share(selected,d=>engine.validateDeck(d));}catch(e){notify(e.message);}};
$('import-code').onclick=()=>ArtifactDeckShare.importDeck({cards:ARTIFACT_CARDS,validate:d=>engine.validateDeck(d),confirmLabel:T('导入并选用','Import & use'),explanation:T('导入后选用此构筑，可点击确认构筑并准备。不会覆盖你的单人构筑。','The imported deck becomes your selection — click Lock deck & ready up. Your single-player decks are untouched.'),onConfirm:raw=>{if(lockedDeck())throw Error(T('请先取消准备再导入构筑','Unready before importing a deck'));const deck=valid(raw);localStorage.setItem('artifact.online.importedDeck',JSON.stringify(deck));decks.push(deck);selected=deck;renderDecks();notify(T('分享构筑已导入并选用，可以确认准备。','Shared deck imported and selected — you can ready up.'));}});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(selected,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='artifact-deck.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const d=JSON.parse(localStorage.getItem('artifact.online.importedDeck')||'null');if(d)decks.push(valid(d));}catch{}
$('resume-list').onclick=e=>{const b=e.target.closest('[data-code]');if(b)task(()=>join(b.dataset.code));};
function syncMatchControls(){const active=matching();$('create').disabled=busy||active||matchBusy;$('join-form').querySelectorAll('button,input').forEach(el=>el.disabled=busy||active||matchBusy);$('match-join').hidden=active;$('match-join').disabled=matchBusy||matchOffline;$('match-cancel').hidden=!active;$('match-cancel').disabled=entering;$('match-retry').hidden=!matchOffline;$('match-retry').disabled=matchBusy;$('match-ready').disabled=matchBusy||matchOffline||match.mineReady||match.status!=='matched'||ArtifactMatchmaking.remaining(match.deadline,Date.now()+serverOffset)<=0;}
function matchClock(){const now=Date.now()+serverOffset;$('match-clock').textContent=match.status==='queued'?`${T('已等待','Waiting')} ${Math.max(0,Math.floor((now-match.queuedAt)/1000))} ${T(' 秒 · 排队 ','s · ')}${match.queueCount||0} ${T(' 人',' in queue')}`:match.status==='matched'?`${T('准备倒计时','Ready timer')} ${ArtifactMatchmaking.remaining(match.deadline,now)} ${T(' 秒','s')}` :'';syncMatchControls();}
